"""Report packed-token full-matrix results, retaining each regression."""
import json,statistics
from pathlib import Path
H=Path(__file__).resolve().parent;data=json.loads((H/'comparison.json').read_text());rows=data['rows'];complete=[r for r in rows if r['complete']]
flags=[r for r in complete if r['metrics']['runtime_ns']['delta_percent']>5 and sum(p['runtime_delta_percent']>0 for p in r['pairs'])>=3]
summary=[]
for family in ('sparse','dense','cogentco'):
 rs=[r for r in complete if r['family']==family];item={'family':family,'complete_cells':len(rs)}
 for key in ('runtime_ns','setup_ns','rss_bytes'):
  ds=[r['metrics'][key]['delta_percent'] for r in rs];item[key]={'lower_cells':sum(d<0 for d in ds),'median_cell_change':statistics.median(ds) if ds else None,'min':min(ds) if ds else None,'max':max(ds) if ds else None}
 summary.append(item)
(H/'assessment.json').write_text(json.dumps({'failed_processes':len(data['failed']),'complete_cells':len(complete),'flagged_cells':flags,'families':summary,'scope':'Engineering screen >5% runtime increase and >=3 slower pairs; not significance. No automatic integration.'},indent=2)+'\n')
lines=['# HDT 64-byte tokens: extended reference matrix','','## Decision','']
if data['failed'] or len(complete)!=38:lines+=['Evidence is incomplete: keep the patch isolated and resolve failed cases.']
elif flags:lines+=[f'{len(flags)} cells meet the predeclared runtime regression screen. Retain the candidate separately and investigate them before integration. Memory improvements must not hide runtime regressions.']
else:lines+=['No cell meets the predeclared runtime regression screen. This supports the candidate on this optimization matrix, not universal improvement. Review remaining workload coverage before integration.']
lines+=['','Exact same [candidate and binary pair as the pilot](../2026-10-08-hdt-packed-tokens/README.md): four optional token indices encoded with NonZeroUsize, 96→64 bytes per token on this 64-bit target. No join/reroot optimization, page preparation or other candidate is combined. Production core remains unchanged.','','## Method','','304 planned processes; 38 cells; four adjacent pairs/cell with 2/2 balanced order and seed 42 shuffle. All processes run sequentially. The matrix covers sparse path/blocks at 100k/1M with 10/50/90% queries, dense 512 controls and Cogentco 197, each fresh/warmed. It is the full optimization matrix, not all 74 cells or all engines of the competitor ranking. [Protocol](protocol.md).','','Changes are `100*(after median/before median-1)`. Negative runtime means improvement. Family summaries are unweighted medians of cell changes, not aggregate throughput. Setup is separate; workload wall includes checking, sampling and timer overhead. Warmed uses an untimed replay on a separate graph; no answer cache/hardware cache flush. Peak RSS is the whole process including trace, allocator retention and harness, not graph-only or token-only memory.','','## Family overview','','| Family | Cells | Faster medians | Median runtime change | Median RSS change | Median setup change |','|---|---:|---:|---:|---:|---:|']
for s in summary:
 if s['complete_cells']:lines.append(f"| {s['family']} | {s['complete_cells']} | {s['runtime_ns']['lower_cells']} | {s['runtime_ns']['median_cell_change']:+.2f}% | {s['rss_bytes']['median_cell_change']:+.2f}% | {s['setup_ns']['median_cell_change']:+.2f}% |")
lines+=['','## Every measured cell','','| Workload | Nodes | Query % | Regime | Before ms | After ms | Runtime change | Faster pairs | RSS before MiB | RSS after MiB | RSS change | Setup change | Flag |','|---|---:|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|---|']
for r in rows:
 if not r['complete']:lines.append(f"| {r['workload']} | {r['nodes']} | {r['query_percent']} | {r['regime']} | incomplete | — | — | — | — | — | — | — | investigate |");continue
 m=r['metrics'];t=m['runtime_ns'];rss=m['rss_bytes'];q=r['query_percent'] if r['query_percent'] is not None else '—'
 lines.append(f"| {r['workload']} | {r['nodes']} | {q} | {r['regime']} | {t['before']['median']/1e6:.3f} | {t['after']['median']/1e6:.3f} | {t['delta_percent']:+.2f}% | {r['pairs_faster']}/4 | {rss['before']['median']/2**20:.1f} | {rss['after']['median']/2**20:.1f} | {rss['delta_percent']:+.2f}% | {m['setup_ns']['delta_percent']:+.2f}% | {'investigate' if r in flags else '—'} |")
lines+=['','## Limits and preservation','','The deterministic token payload saving is 33.33%; it must not replace measured total RSS. Prior A/A studies showed short-path timing variability, and this study does not eliminate it. Four pairs per cell do not establish statistical significance or equivalence. Preserve flags even where memory improves. No data are pooled with pilot/history; no outliers removed. Operation totals, p50, p95, p99, ranges and each paired delta remain in [comparison.json](comparison.json); percentiles are not pooled.','','Fixed operation count changes the mutated fraction as graphs grow. Cogentco is a real topology with synthetic outages, not a fraud-detection benchmark. No competitor superiority can be inferred from this two-binary study.','','## Validation','',f"Complete cells: {len(complete)}/38; failed processes: {len(data['failed'])}. Trace fingerprints, oracle answers, operation counts and paired HDT counters are checked. [Audit](audit.json) checks frozen sources, exact pilot binary hashes, measured artifacts and balanced order. The candidate already passed full workspace formatting, Clippy, tests/doctests and Rustdoc in [pilot verification](../2026-10-08-hdt-packed-tokens/reconstruction-verification.json). No new Rust changes were made for this collection.",'','[Assessment](assessment.json) retains all flags. [Patch inventory](../../docs/experiments/2026-10-06-hdt-candidates.md) preserves this candidate independently of temporary builds. No staging, commit or push was performed.']
(H/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,indent=2));print('Flags',len(flags))
